import{z as B,x as n,o as s,c as A,q as r,j as o,D as t,d as e,s as E,S as c,b as l}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"时钟虚拟化","description":"","frontmatter":{"title":"时钟虚拟化","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/clock-virtualization.md","filePath":"cs/clock-virtualization.md","lastUpdated":1791413859000}'),p={name:"cs/clock-virtualization.md"};function d(m,a,u,C,k,h){const i=n("Mermaid");return s(),A("div",null,[a[2]||(a[2]=r('<h1 id="时钟虚拟化" tabindex="-1">时钟虚拟化 <a class="header-anchor" href="#时钟虚拟化" aria-label="Permalink to &quot;时钟虚拟化&quot;">​</a></h1><div class="epigraph"><p>客户 TSC 与时钟设备若按真实硬件跑，迁移与偷时间会让时间跳；KVM 用 pvclock/kvm-clock 或缩放 TSC 给一个稳定故事。</p><footer>—— 据 Linux kvmclock；Xen pvclock；[tickless](/cs/tickless-nohz) 与 [cyclictest](/cs/latency-measurement) 为时间先修</footer></div><p><a href="/cs/interrupt-virtualization">posted interrupt</a> 处理 IRQ。<a href="/cs/timer-wheel">timer wheel</a> 在客户内核另有一份。缺口是 <strong>客户看见的时间</strong>：TSC 偏移、偷时间、迁移。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TSC 在迁移到另一台主机时不同步。无 pv：NTP 疯。kvm-clock：共享页写宿主持续时钟。缺口：<code>clocksource</code> 选择；与 <a href="/cs/tickless-nohz">NO_HZ</a> 客户。本课不把 NTP 算法重写。<span class="marginnote">术语翻译：TSC（时间戳计数器）是 CPU 里一个随时钟周期不断加一的寄存器，软件读它拿高精度时间。麻烦在于它数的是「这台物理 CPU 的周期」——虚拟机一搬到别的主机，计数起点就换了，客户看见的时间会突然跳一大截。</span></p><p><span class="marginnote">TSC scaling 硬件可乘偏移。对象是客户时间，不是 RTC 芯片更换。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>QEMU/KVM 提供 kvm-clock 页或 PIT/HPET 模拟。对照 <a href="/cs/paravirtualization">半虚拟</a>：时钟也是 PV。对照 DAX：无关。对照 <a href="/cs/cpuidle-cstate">cpuidle</a>：宿主编排 halt，客户 TSC 仍应前进策略一致。</p>',8)),(s(),o(c,null,{default:t(()=>[E(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E5%AE%BF%E4%B8%BB%E7%A8%B3%E5%AE%9A%E6%97%B6%E9%92%9F%22%5D%20--%3E%20PV%5B%22pvclock%20%E5%85%B1%E4%BA%AB%E9%A1%B5%22%5D%0A%20%20PV%20--%3E%20G%5B%22%E5%AE%A2%E6%88%B7%20clocksource%22%5D%0A%20%20MIG%5B%22%E8%BF%81%E7%A7%BB%22%5D%20--%3E%20ADJ%5B%22TSC%20%E5%81%8F%E7%A7%BB%E8%B0%83%E6%95%B4%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[e("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,[e("时钟虚拟化把「时间是共享真理」在 VM 里重新定义，使迁移与超售（偷时间）不毁掉客户内核会计。超售过度仍会让客户觉得 CPU 被偷。不要写成相对论。与 "),l("a",{href:"/cs/fairness-metrics"},"fairness"),e("：客户 CFS 看自己的时钟。")],-1)),(s(),o(c,null,{default:t(()=>[E(i,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20MIG%5B%22VM%20%E4%BB%8E%E4%B8%BB%E6%9C%BA%20A%20%E8%BF%81%E5%88%B0%E4%B8%BB%E6%9C%BA%20B%22%5D%20--%3E%20DIFF%7B%22%E4%B8%A4%E5%8F%B0%E4%B8%BB%E6%9C%BA%E7%9A%84%20TSC%20%E8%AF%BB%E6%95%B0%E6%98%AF%E5%90%A6%E7%9B%B8%E5%90%8C%EF%BC%9F%22%7D%0A%20%20DIFF%20--%3E%7C%22%E5%90%A6%22%7C%20OFF%5B%22%E7%AE%97%E5%87%BA%E5%81%8F%E7%A7%BB%E9%87%8F%E5%86%99%E8%BF%9B%20pvclock%20%E5%85%B1%E4%BA%AB%E9%A1%B5%22%5D%0A%20%20OFF%20--%3E%20SW%5B%22%E5%AE%A2%E6%88%B7%E6%AF%8F%E6%AC%A1%E8%AF%BB%E9%92%9F%E7%BB%9F%E4%B8%80%E5%8A%A0%E4%B8%8A%E5%81%8F%E7%A7%BB%22%5D%0A%20%20SW%20--%3E%20SAME%5B%22%E5%AE%A2%E6%88%B7%E5%86%85%E6%A0%B8%E7%9C%8B%E8%A7%81%E6%97%B6%E9%97%B4%E8%BF%9E%E7%BB%AD%EF%BC%8C%E4%BC%9A%E8%AE%A1%E4%B8%8D%E4%B9%B1%22%5D%0A%20%20DIFF%20--%3E%7C%22%E6%98%AF%22%7C%20RAW%5B%22%E8%A3%B8%20TSC%20%E5%8F%AF%E7%9B%B4%E6%8E%A5%E6%B2%BF%E7%94%A8%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">这张图回答「迁移那一刻时间为什么没有跳」：宿主在共享页里交出「偏移量 + 缩放系数」这两个数，客户每次读钟都按它折算。前提是切换要原子——偏移换到一半被客户读到，时间照样倒流。</span></p><p>错误 clocksource 导致客户 hang 或时间倒流检测。<span class="marginnote">常见误区：以为客户里选哪种 <code>clocksource</code> 只是性能口味。选错时钟源（比如在一台 TSC 不可信的机器上硬用 TSC），轻则 NTP 反复拉锯校不准，重则时间倒流触发内核告警，定时器、超时、负载统计全面失灵——时间源是内核会计的地基。</span></p><p><span class="marginnote">直觉类比「偷时间」：你按小时租了跑步机，前台却时不时把你挪开给别人让位——你没跑满时长，账单却照算。宿主超售 CPU 时客户被挂起而不自知，所以要把 steal 时间显式报给客户，客户内核的负载统计才不至于把「没分到 CPU」误判成「程序自己慢」。</span></p><p>实现上：偷时间（steal）要报给客户，否则负载计算偏了。迁移瞬间 TSC 偏移必须原子切换。客户选 tsc 还是 kvm-clock 决定能否跨机。 读法上只引用<a href="/cs/interrupt-virtualization">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「虚拟化与隔离进阶 / Hypervisor」课序里，对象是 <strong>时钟虚拟化</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 VDSO 时钟。不保证嵌套 VM 的 TSC。下一课内存超售：气球。</p><p>版本字段会变，课序钉的是机制对象「时钟虚拟化」，不是某一主线内核的结构体名。 后课默认：客户时钟靠 PV 或 TSC 缩放。用气球收回客户内存，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>客户时钟需 PV 或 TSC 偏移，才能迁移与超售。</li><li>kvm-clock 是共享页协议。</li><li>内存气球是下一课。</li><li>出处：kvmclock；Xen pvclock；KVM。</li></ul>',11))])}const S=B(p,[["render",d]]);export{F as __pageData,S as default};
